import json
from pathlib import Path
p=Path('/workspace/sites/olympiad-atlas')
new=[]
def add(year,num,rating,topic,tags,statement,reason,shared=None,solution=None):
 url=f'https://web.evanchen.cc/exams/JMO-{year}-notes.pdf'
 a=[dict(competition='USAJMO',year=year,number=str(num))]
 if shared:a.append(dict(competition='USAMO',year=year,number=str(shared)))
 new.append(dict(id=f'us-usajmo-{year}-{num}',country='United States',competition='USAJMO',year=year,number=str(num),statement=statement,solution=solution or f'[View Evan Chen’s worked solution notes]({url}).',sourceUrl=url,solutionUrl=url,solutionKind='original-exposition' if solution else 'source-link',topic=topic,tags=tags.split('|'),difficulty=rating,ratingReason=reason,reviewStatus='individually-assessed',notes='Statement restated in original wording. Evan Chen’s author-maintained notes checked; these are not labelled official solutions.',appearances=a))
add(2026,1,4,'Number theory','Integer inequalities|Factorisation',r'Distinct positive integers $a,b,c$ satisfy $ab+c=c^2$. Prove $(a-b)^2\ge4c$.','The inequality is equivalent to a+b at least 2c. Factoring ab=c(c−1) and using distinctness places a and b on opposite sides of c; integrality then sharpens a strict bound by one. It is a compact number-theoretic inequality rather than a long calculation.')
add(2026,2,6.5,'Combinatorics','Circular arrangements|Invariants|GCD|Reachability',r'There are $m$ distinguishable foxes and $n$ distinguishable rabbits in $m+n$ fixed seats around a circle. A fox may swap seats with a rabbit in an adjacent seat. From a fixed starting arrangement, how many arrangements can be reached? Rotations and reflections count separately.','Preserving each species’ cyclic order is only the first invariant. Crossing the fixed cut shifts their index offsets in opposite directions, leaving a gcd constraint. One must then construct all allowed offsets and show every species pattern contributes equally.')
add(2026,4,6,'Geometry','Excentres|Angle bisectors|Circumcircles',r'Triangle $ABC$ has circumcircle $\omega$ and circumcentre $O$. Lines $AO$ and $BC$ meet at $D$. Let $X,Y$ be the $A$-excentres of the nondegenerate triangles $ABD,ACD$, respectively. Prove that $X\in\omega$ implies $Y\in\omega$.','Interpreting the two angle bisectors as arc-midpoint conditions forces BC to be a diameter. In that simplified right-triangle configuration the second excentre is explicit. A correct solution must also control internal versus external bisectors, which rules out a casual angle chase.')
add(2026,5,7,'Combinatorics','Digits|Carry arithmetic|Recurrences',r'Call a positive integer $n$ solitary if, for every decomposition $n=a+b$ into nonnegative integers, at least one of $a,b$ has a digit $1$ in its decimal expansion. How many solitary integers are less than $10^{2026}$?','Analysing the carry in the final digit gives a recursive description of representability as a sum of two numbers avoiding 1. The hard part is proving the complete exceptional digit pattern, including all carries; only then does the geometric-series count become straightforward.',shared=4)
add(2026,6,6,'Geometry','Extremal principle|Convexity|Dissections',r'Draw $2026$ circles on a red sheet of paper, allowing different radii, and colour the interior of one circle black. Cut along every drawn circumference. If there are at least two black pieces, can all the black pieces be congruent?','A point contained in as many disks as possible identifies a black piece with only outward-curving boundary, hence a convex piece. Any genuine circular cut also creates a piece with an inward-curving boundary. Finding this extremal geometric invariant gives a short but unexpected impossibility proof.')
add(2025,1,5,'Algebra','Functions|Bijections|Finite differences',r'For any function $f:\mathbb Z\to\mathbb Z$, prove that infinitely many integers $c$ make $x\mapsto f(x)+cx$ fail to be a bijection.','Every negative adjacent difference supplies a noninjective slope. If only finitely many bad slopes existed, these differences would be bounded, so adding a sufficiently large linear term creates a strictly increasing function with jumps greater than one, contradicting surjectivity.')
add(2025,2,6,'Number theory','Bases|Digits|Modular arithmetic',r'Fix positive integers $k,d$. Prove that, for all sufficiently large odd positive integers $n$, every digit of $n^k$ written in base $2n$ is greater than $d$.','For each digit position, the remainder modulo (2n)^j is a nonzero odd multiple of n^j. This gives a simultaneous lower bound on every digit once n is large. The key is studying suffix remainders, with careful control of the number of digits.',shared=1)
add(2025,5,5.5,'Geometry','Orthocentre|Reflection|Circumcentres',r'In acute triangle $ABC$, let $H$ be the orthocentre, $F$ the foot of the altitude from $C$, and $P$ the reflection of $H$ in $BC$. The circumcircle of $AFP$ meets line $BC$ at distinct points $X,Y$. Prove $CX=CY$.','Introducing the antipode of B creates a parallelogram involving H and an isosceles trapezoid involving P. The midpoint of the resulting segment is the circle’s centre, and its perpendicular to BC passes through C. The auxiliary circumcentre construction is the main insight.',shared=4)
add(2024,2,5.5,'Combinatorics','Involutions|Parity|Rectangles',r'Partition the $4mn$ lattice points $(x,y)$ with $1\le x\le2m$ and $1\le y\le2n$ into the vertex sets of $mn$ axis-parallel rectangles. Prove that the number of such partitions is odd.','Swapping two columns pairs most configurations. A fixed configuration must keep those columns self-contained, so its count factors into a smaller instance and an odd pairing count. The fixed-point classification is the important step in this parity induction.')
add(2024,4,5.5,'Combinatorics','Permutations|Counting|Symmetry',r'Colour an $n\times n$ grid red or blue, where $n\ge3$. Call it orderly if every row permutation can be undone by some column permutation, and every column permutation can be undone by some row permutation. How many orderly colourings are there?','A column containing r red cells forces all binomial(n,r) row-permuted versions to occur among just n columns. This sharply restricts r, after which the two permutation-matrix patterns and monochromatic cases can be counted. The orbit-size bound is the decisive observation.')
add(2024,5,5.5,'Algebra','Functional equations|Symmetry|Substitution',r'Find all functions $f:\mathbb R\to\mathbb R$ satisfying $f(x^2-y)+2yf(x)=f(f(x))+f(y)$ for all real $x,y$.','Strategic substitutions first force f(0)=0, evenness, and f(x squared)=x squared times f(x). Applying the equation to two squares and swapping them then forces f to be a constant multiple of x squared. The symmetry avoids a much longer pointwise case analysis.')
add(2024,6,7,'Geometry','Tangency|Homothety|Auxiliary constructions',r'Inside acute triangle $ABC$, choose $D$ with $\angle DAC=\angle ACB$ and $\angle BDC=90^\circ+\angle BAC$. Choose $E$ on ray $BD$ so that $AE=EC$, and let $M$ be the midpoint of $BC$. Prove that $AB$ is tangent to the circumcircle of $BEM$.','Completing an isosceles trapezoid and reflecting B through E turns the midpoint condition into a homothety. A newly cyclic quadrilateral then supplies the tangent-angle relation. The coordinated auxiliary construction places this at the upper edge of the target.',shared=5)

data=json.loads((p/'data/americas.json').read_text());ids={x['id'] for x in new}
data=[x for x in data if x['id'] not in ids]+new
(p/'data/americas.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
c=json.loads((p/'research/americas-coverage.json').read_text())
full={2026:[4,6.5,9,6,7,6],2025:[5,6,7.5,3,5.5,8],2024:[3,5.5,7.5,5.5,5.5,7]}
c['fullyScreened']=[x for x in c['fullyScreened'] if not(x['competition']=='USAJMO' and x['year'] in full)]
for year,ratings in full.items():c['fullyScreened'].append(dict(competition='USAJMO',year=year,ratings=ratings,source=f'https://web.evanchen.cc/exams/JMO-{year}-notes.pdf'))
for year,ratings in {2026:{'4':7},2025:{'1':6,'4':5.5},2024:{'5':7}}.items():
 existing=next((x for x in c['partiallyScreened'] if (x['competition'],x['year'])==('USAMO',year)),None)
 if existing:existing['ratings'].update(ratings)
 else:c['partiallyScreened'].append(dict(competition='USAMO',year=year,ratings=ratings,pending=[str(i) for i in range(1,7) if str(i) not in ratings]))
c['papersScreened']=len(c['fullyScreened'])
c['problemAppearancesScreened']=sum(len(x['ratings']) for x in c['fullyScreened']+c['partiallyScreened'])
c['uniqueIncluded']=len(data)
c['gaps'][1]='US: USAMO 2008 Q3, 2009 Q3 and most years outside 2006–2014 remain pending, except listed shared recent problems. USAJMO 2024–2026 fully screened; 2021 partially screened; other years pending.'
c['gaps'][2]='USAMO2026 Q1 source notes explicitly withdraw the key inequality proof; not rated or published without an independent proof. Other recent USAMO nonshared questions are being assessed.'
(p/'research/americas-coverage.json').write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n')
print('Total',len(data))
